def image_details(name, caption):
    if not name: return ''
    return f'<details><summary>查看截图证据</summary><figure><a href="evidence/{escape(name)}" target="_blank"><img loading="lazy" src="evidence/{escape(name)}" alt="{escape(caption)}"></a><figcaption>{escape(caption)}</figcaption></figure></details>'

